\title{Exact Interior Fiber Cardinality for the Full-Strength Logistic Map}
\author{Aristotle}
\date{August 2, 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $L:[0,1]\to[0,1]$ be the full-strength logistic map $L(x)=4x(1-x)$. For an interior target $y$, define the lower and upper inverse branches
\[
B_0(y)=\frac{1-\sqrt{1-y}}2,\qquad B_1(y)=\frac{1+\sqrt{1-y}}2.
\]
A binary word of length $n$ recursively selects these branches and determines an $n$-step predecessor of $y$. We prove that this decoding is a bijection from $\{0,1\}^n$ onto $\{x\in(0,1):L^n(x)=y\}$. Consequently every interior target has exactly $2^n$ interior preimages under $L^n$. The proof isolates three mechanisms: inverse branches preserve the open interval, the midpoint separates them and prevents collisions, and the quadratic formula proves exhaustion. We also present enumeration algorithms, numerical diagnostics, and implications for backward inference, finite-precision dynamics, and orbit-suffix ambiguity.
\end{abstract}

\section{Introduction}
The logistic family $x\mapsto rx(1-x)$ is a basic model of nonlinear population dynamics and deterministic chaos. At $r=4$, the map sends the unit interval onto itself and folds it around its midpoint. Forward evolution is single-valued, whereas a typical backward step has two choices. Repetition suggests a complete binary tree of histories, but that picture alone does not prove an exact count: branches might leave the domain, distinct paths might collide, or the proposed formulas might omit solutions.

We resolve all three issues for interior targets. If $n\geq0$ and $0<y<1$, then
\[
\card{\{x\in(0,1):L^n(x)=y\}}=2^n.
\]
More strongly, the proof constructs a canonical bijection with binary words of length $n$. The restriction to the interior is structural. At $y=1$ the inverse branches collide at the critical point $1/2$, while at $y=0$ they reach the endpoints.

\section{Definitions and setup}

\begin{definition}[Full-strength logistic map]
Define $L:[0,1]\to[0,1]$ by
\[
L(x)=4x(1-x).
\]
Its iterates are $L^0(x)=x$ and $L^{n+1}(x)=L^n(L(x))$.
\end{definition}
The identity $L(x)=1-(2x-1)^2$ shows that $L$ maps $[0,1]$ into itself.

\begin{definition}[Interior fiber]
For $n\in\N$ and $y\in(0,1)$, define
\[
\F_n(y)=\{x\in(0,1):L^n(x)=y\}.
\]
\end{definition}

Solving $L(x)=y$ yields $(1-2x)^2=1-y$.

\begin{definition}[Inverse branches]
For $y\in[0,1]$, let
\[
B_0(y)=\frac{1-\sqrt{1-y}}2,\qquad
B_1(y)=\frac{1+\sqrt{1-y}}2.
\]
\end{definition}

Let $\{0,1\}^n$ be the binary words $\varepsilon=(\varepsilon_1,\ldots,\varepsilon_n)$, with one empty word $()$ at length zero.

\begin{definition}[Backward decoding]
Set $D_{()}(y)=y$, and recursively define
\[
D_{(\varepsilon_1,\ldots,\varepsilon_n)}(y)
=B_{\varepsilon_1}\bigl(D_{(\varepsilon_2,\ldots,\varepsilon_n)}(y)\bigr).
\]
\end{definition}
The first symbol describes whether the original seed lies on the lower or upper side; the remaining symbols reconstruct its immediate successor.

\section{One-step inverse geometry}

\begin{lemma}[Right-inverse identity]
If $0\leq y\leq1$ and $b\in\{0,1\}$, then $L(B_b(y))=y$.
\end{lemma}
\begin{proof}
Put $s=\sqrt{1-y}$, so $s^2=1-y$. For either sign,
\[
4\left(\frac{1\pm s}{2}\right)\left(1-\frac{1\pm s}{2}\right)
=(1+s)(1-s)=1-s^2=y.
\]
\end{proof}

\begin{lemma}[Interior preservation]
If $0<y<1$, then $0<B_b(y)<1$ for $b\in\{0,1\}$.
\end{lemma}
\begin{proof}
The hypotheses imply $0<\sqrt{1-y}<1$. Substitution in $(1\pm\sqrt{1-y})/2$ gives both strict bounds.
\end{proof}

\begin{lemma}[Branch separation]
If $0<y<1$, then
\[
B_0(y)<\frac12<B_1(y).
\]
\end{lemma}
\begin{proof}
This follows from the strict positivity of $\sqrt{1-y}$.
\end{proof}

\begin{lemma}[Exhaustion of one-step preimages]
Let $x\in(0,1)$, let $y\in(0,1)$, and suppose $L(x)=y$. Then exactly one $b\in\{0,1\}$ satisfies $x=B_b(y)$.
\end{lemma}
\begin{proof}
The equation gives $1-y=(1-2x)^2$. If $x\leq1/2$, then $\sqrt{1-y}=1-2x$ and $x=B_0(y)$. If $x>1/2$, then $\sqrt{1-y}=2x-1$ and $x=B_1(y)$. Branch separation proves uniqueness.
\end{proof}

\begin{lemma}[Interior reflection]
If $x\in[0,1]$ and $L^n(x)\in(0,1)$, then every state $L^j(x)$, $0\leq j\leq n$, belongs to $(0,1)$.
\end{lemma}
\begin{proof}
All states are in $[0,1]$ by forward invariance. Since $L(0)=L(1)=0$, any point in $[0,1]$ whose image is positive cannot be an endpoint. Starting from the interior final state and applying this observation backward proves the claim.
\end{proof}

\section{Validity and uniqueness of decoded histories}

\begin{lemma}[Decoded points are interior]
For $0<y<1$, every $n\geq0$, and every $\varepsilon\in\{0,1\}^n$, one has $D_\varepsilon(y)\in(0,1)$.
\end{lemma}
\begin{proof}
Induct on word length. The empty word gives $y$. For a nonempty word the tail is interior by induction, and either inverse branch preserves the interior.
\end{proof}

\begin{lemma}[Decoded words are valid predecessors]
For $0<y<1$ and $\varepsilon\in\{0,1\}^n$,
\[
L^n(D_\varepsilon(y))=y.
\]
\end{lemma}
\begin{proof}
Induct on $n$. For $\varepsilon=(b,\tau)$, the right-inverse identity gives
\[
L(D_\varepsilon(y))=L(B_b(D_\tau(y)))=D_\tau(y).
\]
The induction hypothesis cancels the remaining branches.
\end{proof}

\begin{theorem}[Uniqueness of binary addresses]
Let $0<y<1$. If $\varepsilon,\delta\in\{0,1\}^n$ and $D_\varepsilon(y)=D_\delta(y)$, then $\varepsilon=\delta$.
\end{theorem}
\begin{proof}
Induct on $n$. Write positive-length words as $\varepsilon=(b,\tau)$ and $\delta=(c,\sigma)$. Applying $L$ to the equality cancels the outer branches and gives $D_\tau(y)=D_\sigma(y)$. Thus $\tau=\sigma$ by induction. Their common decoded tail is interior. If $b\neq c$, branch separation puts one full decoded value below $1/2$ and the other above $1/2$, contradicting equality. Hence $b=c$ as well.
\end{proof}

\begin{corollary}
For $0<y<1$, $\card{\F_n(y)}\geq2^n$.
\end{corollary}
\begin{proof}
There are $2^n$ binary words, each gives a point of the fiber, and uniqueness makes those points distinct.
\end{proof}

\section{Exhaustion and exact cardinality}

\begin{theorem}[Existence of a binary address]
Let $n\geq0$, $0<y<1$, and $x\in(0,1)$. If $L^n(x)=y$, then some $\varepsilon\in\{0,1\}^n$ satisfies $D_\varepsilon(y)=x$.
\end{theorem}
\begin{proof}
Induct on $n$. For $n=0$, the equation gives $x=y$, represented by the empty word. For the induction step, suppose $L^{n+1}(x)=y$ and set $z=L(x)$. Interior reflection gives $z\in(0,1)$. By induction there is a tail $\tau$ with $D_\tau(y)=z$. Since $L(x)=z$, one-step exhaustion gives $b\in\{0,1\}$ with $x=B_b(z)$. Therefore
\[
x=B_b(D_\tau(y))=D_{(b,\tau)}(y).
\]
\end{proof}

\begin{theorem}[Interior Fiber Parametrization]
For every $n\geq0$ and $y\in(0,1)$,
\[
\F_n(y)=\{D_\varepsilon(y):\varepsilon\in\{0,1\}^n\}.
\]
The map $\varepsilon\mapsto D_\varepsilon(y)$ is a bijection from $\{0,1\}^n$ to $\F_n(y)$.
\end{theorem}
\begin{proof}
Validity places every decoded value in the fiber. Address existence proves surjectivity, and address uniqueness proves injectivity.
\end{proof}

\begin{theorem}[Exact Interior Fiber Cardinality]
For every integer $n\geq0$ and target $0<y<1$,
\[
\card{\{x\in(0,1):L^n(x)=y\}}=2^n.
\]
\end{theorem}
\begin{proof}
The parametrization theorem gives a bijection with $\{0,1\}^n$, which has two independent choices in each of $n$ positions and hence cardinality $2^n$.
\end{proof}

For $n=0$, this says that the identity fiber is the singleton $\{y\}$, consistently with $2^0=1$.

\section{Algorithms}

\begin{algorithm}[Single-address branch decoding]
Given $y\in(0,1)$ and $\varepsilon=(\varepsilon_1,\ldots,\varepsilon_n)$, initialize $z\leftarrow y$. For $j=n,n-1,\ldots,1$, set
\[
z\leftarrow\frac{1+(2\varepsilon_j-1)\sqrt{1-z}}2.
\]
Return $z$.
\end{algorithm}
This uses $n$ square roots, $O(n)$ arithmetic operations, and $O(1)$ auxiliary storage. In exact arithmetic the output is $D_\varepsilon(y)$.

\begin{algorithm}[Complete inverse-tree enumeration]
Begin with $S_0=[y]$. For $j=1,\ldots,n$, replace every $z\in S_{j-1}$ by $B_0(z)$ and $B_1(z)$, producing $S_j$. Return $S_n$.
\end{algorithm}
The returned list is exactly $\F_n(y)$ without repetition. The total number of branch evaluations is
\[
2+4+\cdots+2^n=2^{n+1}-2.
\]
Thus time and output storage are $\Theta(2^n)$, which is optimal for explicit enumeration.

For numerical diagnostics define the forward residual
\[
r_n(x;y)=|L^n(x)-y|.
\]
A floating-point implementation generally produces a small nonzero residual because square roots and arithmetic are rounded. This diagnostic does not replace the exact argument.

\section{Numerical and geometric observations}
For $y=0.7$, the immediate predecessors are
\[
B_0(0.7)\approx0.2261387212,\qquad B_1(0.7)\approx0.7738612788.
\]
They sum to one and both map to $0.7$. At depth two there are four distinct points, while depth six has $64$.

The points are not uniformly spaced. The branch derivatives satisfy
\[
|B_0'(y)|=|B_1'(y)|=\frac{1}{4\sqrt{1-y}},
\]
which grows near $y=1$. The symmetry
\[
B_1(y)=1-B_0(y)
\]
reflects immediate predecessors about $1/2$ and induces related symmetries at deeper levels.

\section{Dynamical interpretation and applications}
The map is strictly increasing on $[0,1/2]$ and strictly decreasing on $[1/2,1]$. Each restriction maps onto $[0,1]$. A forward step merges one lower-half state and one upper-half state, thereby erasing the branch label. After $n$ steps, reconstruction requires exactly $n$ labels. The fiber theorem identifies these labels with all binary words of length $n$.

Suppose an observer sees an exact interior state after $n$ transitions but not the preceding states. Exactly $2^n$ interior initial states are compatible with that observation. All share the same later orbit because forward evolution from the observed state is deterministic. Hence any deterministic statistic depending only on that suffix is constant across the fiber. This is an obstruction to unique backward inference, not by itself a claim of cryptographic security: finite precision, side channels, and output design can reveal additional information.

The substitution $x=\sin^2\theta$ gives
\[
L(x)=4\sin^2\theta\cos^2\theta=\sin^2(2\theta).
\]
Thus forward iteration doubles angles, and inverse branches select solutions of
\[
2^n\phi\equiv\pm\theta\pmod\pi.
\]
This suggests a closed description by values
\[
\sin^2\left(\frac{s\theta+k\pi}{2^n}\right),\qquad s\in\{-1,1\},
\]
with a nonredundant binary indexing of $k$. The recursive theorem guarantees that a correct indexing must produce exactly $2^n$ distinct interior values.

Uniform angular coordinates induce the arcsine density
\[
\rho(x)=\frac{1}{\pi\sqrt{x(1-x)}}.
\]
The angle-doubling relation and inverse Jacobians suggest its invariance under $L$ and the Lyapunov exponent $\log2$. These measure-theoretic statements are natural continuations of the finite-fiber result.

\section{Boundary behavior and finite precision}
At the upper boundary,
\[
B_0(1)=B_1(1)=\frac12,
\]
so the branches collide at the critical point. At the lower boundary,
\[
B_0(0)=0,\qquad B_1(0)=1,
\]
and both values lie outside the open interval. The complete binary count therefore requires the interior hypotheses.

For fixed-point precision $p$, consider
\[
G_p=\left\{\frac{k}{2^p}:0\leq k\leq2^p\right\}.
\]
Rounding the $2^n$ exact seeds into this grid can leave at most
\[
\min(2^n,2^p+1)
\]
distinct stored values. Rounded equality does not contradict exact injectivity. An exact classification requires an equivalence relation determined by rounding-cell boundaries. Iterated floating-point arithmetic creates additional effects because rounding occurs at every operation and the state space is finite.

\section{Discussion}
The argument exhibits a template for finite-depth fibers of piecewise monotone maps. Explicit inverse branches generate candidates; domain invariance keeps compositions legal; disjoint branch ranges ensure symbolic uniqueness; and local inverse exhaustion proves completeness. For the parameter-$4$ logistic map, both branches are full and the structure repeats uniformly at every interior level.

The parametrization is stronger than a polynomial root count. It labels each predecessor, provides an optimal enumeration algorithm, and identifies the information lost by forward evolution. The fiber is a binary symbolic object represented geometrically by nested radicals.

\section{Future work}
\begin{enumerate}[leftmargin=*]
\item \textbf{Closed trigonometric indexing.} For $0<\theta<\pi/2$, associate each branch word explicitly and uniquely with $\sin^2((s\theta+k\pi)/2^n)$.
\item \textbf{Boundary fiber cardinalities.} Classify the interior fibers over $0$ and $1$, accounting for endpoint exclusion and critical collisions.
\item \textbf{Fixed-point rounding collapse.} Characterize exactly when two branch words enter the same nearest-grid rounding cell and count the resulting equivalence classes.
\item \textbf{Orbit-suffix ambiguity.} Build a precise stream model and characterize observers that are necessarily constant on exact fibers.
\item \textbf{Arcsine invariance.} Use branch Jacobians to prove invariance of $1/(\pi\sqrt{x(1-x)})$ and derive the Lyapunov exponent $\log2$.
\end{enumerate}

\section{Conclusion}
For $L(x)=4x(1-x)$, the lower and upper quadratic inverse branches map the open interval into disjoint halves. Binary compositions yield valid predecessors; midpoint separation prevents collisions; and the quadratic formula exhausts all predecessors. Therefore, for every $n\geq0$ and $0<y<1$,
\[
\F_n(y)=\{D_\varepsilon(y):\varepsilon\in\{0,1\}^n\}
\quad\text{and}\quad
\card{\F_n(y)}=2^n.
\]
The backward binary tree is thus an exact classification rather than a heuristic picture.

