from __future__ import annotations
import math
from typing import Sequence


def inverse_branch(y: float, upper: bool) -> float:
    """Return one of the two inverse branches of 4*x*(1-x)."""
    if not 0.0 <= y <= 1.0:
        raise ValueError("y must belong to [0, 1]")
    root = math.sqrt(max(0.0, 1.0 - y))
    return (1.0 + root) / 2.0 if upper else (1.0 - root) / 2.0


def decode_branch_address(target: float, bits: Sequence[int]) -> float:
    """Decode an n-bit address into an n-step predecessor."""
    if not 0.0 < target < 1.0:
        raise ValueError("target must be interior")
    value = target
    for bit in reversed(bits):
        if bit not in (0, 1):
            raise ValueError("bits must contain only 0 and 1")
        value = inverse_branch(value, bool(bit))
    return value


if __name__ == "__main__":
    print(decode_branch_address(0.7, (0, 1, 1, 0)))

from __future__ import annotations
import math


def inverse_pair(y: float) -> tuple[float, float]:
    """Return the lower and upper predecessors of y."""
    root = math.sqrt(max(0.0, 1.0 - y))
    return (1.0 - root) / 2.0, (1.0 + root) / 2.0


def enumerate_exact_fiber(target: float, depth: int) -> list[float]:
    """Numerically enumerate all branch-coded depth-n predecessors."""
    if not 0.0 < target < 1.0:
        raise ValueError("target must be interior")
    if depth < 0:
        raise ValueError("depth must be nonnegative")
    level = [target]
    for _ in range(depth):
        level = [child for value in level for child in inverse_pair(value)]
    return level


if __name__ == "__main__":
    values = enumerate_exact_fiber(0.7, 5)
    print(len(values), min(values), max(values))

