#!/usr/bin/env python3
"""Plot the inverse tree and the final fiber for the logistic map."""
from __future__ import annotations

import math
from typing import Sequence

import matplotlib.pyplot as plt


def branches(y: float) -> tuple[float, float]:
    root = math.sqrt(max(0.0, 1.0 - y))
    return (1.0 - root) / 2.0, (1.0 + root) / 2.0


def inverse_levels(target: float, depth: int) -> list[list[float]]:
    if not 0.0 < target < 1.0 or depth < 0:
        raise ValueError("use an interior target and nonnegative depth")
    levels = [[target]]
    for _ in range(depth):
        levels.append([child for y in levels[-1] for child in branches(y)])
    return levels


def plot_inverse_tree(target: float = 0.7, depth: int = 6) -> None:
    levels = inverse_levels(target, depth)
    figure, (tree_axis, fiber_axis) = plt.subplots(2, 1, figsize=(11, 8))
    for level_index, level in enumerate(levels[:-1]):
        next_level = levels[level_index + 1]
        for parent_index, parent in enumerate(level):
            for offset in (0, 1):
                child = next_level[2 * parent_index + offset]
                tree_axis.plot(
                    [level_index, level_index + 1], [parent, child],
                    color="#4f46e5" if offset == 0 else "#ec4899", alpha=0.5,
                )
    for level_index, level in enumerate(levels):
        tree_axis.scatter([level_index] * len(level), level, s=14, color="#111827", zorder=3)
    tree_axis.set(title=f"Backward inverse tree for y={target}", xlabel="Backward depth", ylabel="State")
    tree_axis.set_ylim(-0.02, 1.02)
    final = sorted(levels[-1])
    fiber_axis.eventplot(final, orientation="horizontal", colors="#0f766e", lineoffsets=0.5, linelengths=0.8)
    fiber_axis.set(title=f"The {2 ** depth} points in the depth-{depth} fiber", xlabel="Seed x", yticks=[])
    fiber_axis.set_xlim(0, 1)
    figure.tight_layout()
    plt.show()


if __name__ == "__main__":
    plot_inverse_tree()
